import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { validate, dereference } from '@scalar/openapi-parser';
import { describe, expect, it } from 'vitest';

// The committed OpenAPI document (generated by `rigctlweb openapi`) must be valid OpenAPI 3.1,
// so any standard tool can generate a client from it.
const spec = readFileSync(fileURLToPath(new URL('../../../docs/openapi.json', import.meta.url)), 'utf8');

describe('docs/openapi.json', () => {
	it('is valid OpenAPI 3.1', async () => {
		const { valid, errors } = await validate(spec);
		expect(errors ?? []).toEqual([]);
		expect(valid).toBe(true);
	});

	it('resolves every $ref', async () => {
		const { errors, schema } = await dereference(spec);
		expect(errors ?? []).toEqual([]);
		expect(Object.keys((schema?.paths ?? {}) as Record<string, unknown>)).toContain('/api/v1/rigs/{id}/state');
	});
});
